17	// mkRepoAt creates an ordinary working-tree repository.
18	func mkRepoAt(t *testing.T, parts ...string) string {
19		t.Helper()
20		dir := filepath.Join(parts...)
21		if err := os.MkdirAll(filepath.Join(dir, ".git"), 0o755); err != nil {
22			t.Fatalf("creating the repo: %v", err)
23		}
24		return dir
25	}
