27	// linkDir makes a directory link the way the platform makes them.
28	//
29	// os.Symlink to a directory needs SeCreateSymbolicLinkPrivilege on Windows,
30	// which a plain user session does not have unless Developer Mode is on — so
31	// these tests would skip on the very platform the defect was reported from. A
32	// *junction* needs no privilege, and a junction is what was in the report:
33	// `mklink /J` is therefore the Windows path rather than a fallback.
34	func linkDir(t *testing.T, target, link string) {
35		t.Helper()
36		if runtime.GOOS == "windows" {
37			out, err := exec.Command("cmd", "/c", "mklink", "/J", link, target).CombinedOutput()
38			if err != nil {
39				t.Skipf("cannot create a junction here: %v (%s)", err, strings.TrimSpace(string(out)))
40			}
41			return
42		}
43		if err := os.Symlink(target, link); err != nil {
44			t.Skipf("cannot create a directory link here: %v", err)
45		}
46	}
