56	// D59 cause 2: DirEntry.IsDir() reports on the link itself, so a junction to a
57	// directory full of repositories said false and the whole subtree was invisible
58	// to S, F and A.
59	func TestARepositoryBehindALinkIsFound(t *testing.T) {
60		root := t.TempDir()
61		elsewhere := t.TempDir()
62		target := mkRepoAt(t, elsewhere, "linked-repo")
63	
64		linkDir(t, elsewhere, filepath.Join(root, "linked"))
65	
66		found := detectSubRepos(root, false)
67		if !repoSet(found.Repos)[filepath.Join(root, "linked", "linked-repo")] {
68			t.Errorf("detectSubRepos = %v, want the repository behind the link (target %q)", found.Repos, target)
69		}
