72	// The cycle guard the depth limit used to provide by accident. Without it this
73	// test does not fail — it never returns.
74	func TestALinkPointingAtAnAncestorDoesNotLoop(t *testing.T) {
75		root := t.TempDir()
76		repo := mkRepoAt(t, root, "a", "repo")
77		linkDir(t, root, filepath.Join(root, "a", "loop"))
