		t.Fatal("esc did not cancel the prompt")
	}

	m = feed(t, m, cancel)
	if m.mode != ModeNormal || m.fuzzyFinder != nil {
		t.Errorf("mode = %v, fuzzyFinder = %v, want ModeNormal and nil after cancel", m.mode, m.fuzzyFinder)
